// La misma funcionalidad, sin anillos: una función con todo adentro.
const guardados = new Map();
let n = 0;
export async function crearDespachoSimple(textoCuerpo, formato) {
  const { destino, kg } = JSON.parse(textoCuerpo);
  if (!/^\d{4}$/.test(String(destino))) return formato === 'texto' ? 'No se pudo: el destino es un código postal de 4 dígitos' : { codigo: 422, cuerpo: { error: 'el destino es un código postal de 4 dígitos' } };
  if (!(kg > 0 && kg <= 1000)) return formato === 'texto' ? 'No se pudo: el peso va de 0 a 1000 kg' : { codigo: 422, cuerpo: { error: 'el peso va de 0 a 1000 kg' } };
  const centavos = 174000;
  const id = 'd' + (++n);
  guardados.set(id, { id, destino: String(destino), kg: Number(kg), centavos, estado: 'pendiente' });
  return formato === 'texto'
    ? `Despacho ${id} a ${destino}: ${kg} kg, $ ${(centavos / 100).toLocaleString('es-AR', { minimumFractionDigits: 2 })}`
    : { codigo: 201, cuerpo: { id, destino: String(destino), kg: Number(kg), centavos } };
}

// Anillo 1: Caso de uso. Conoce las entidades y define sus propios puertos:
//   repo.guardar(despacho)            (puerto de salida hacia los datos)
//   cotizador.cotizar({destino, kg})  (puerto de salida hacia el proveedor)
//   salida.exito(datos) / salida.rechazo(motivo)   (puerto de salida hacia quien muestra el resultado)
import { nuevoDespacho, ReglaRota } from '../entidades/despacho.mjs';

export function crearDespacho({ repo, cotizador, ids }) {
  // Entrada: un objeto plano. Salida: se le entrega al puerto `salida`, que implementa el anillo de afuera.
  return async function ejecutar({ destino, kg }, salida) {
    try {
      const centavos = await cotizador.cotizar({ destino, kg });
      const d = nuevoDespacho({ id: ids.nuevo(), destino, kg, centavos });
      await repo.guardar(d);
      salida.exito({ id: d.id, destino: d.destino, kg: d.kg, centavos: d.centavos });   // datos simples, no la entidad
    } catch (e) {
      if (e instanceof ReglaRota) return salida.rechazo(e.message);
      throw e;
    }
  };
}

// Anillo 2: Adaptadores de interfaz. Cada presentador da formato; el caso de uso no sabe cuál usa.
const pesos = (c) => `$ ${(c / 100).toLocaleString('es-AR', { minimumFractionDigits: 2 })}`;

export function presentadorJson() {
  let r;
  return { exito: (d) => { r = { codigo: 201, cuerpo: d }; }, rechazo: (m) => { r = { codigo: 422, cuerpo: { error: m } }; }, resultado: () => r };
}
export function presentadorTexto() {
  let r;
  return { exito: (d) => { r = `Despacho ${d.id} a ${d.destino}: ${d.kg} kg, ${pesos(d.centavos)}`; }, rechazo: (m) => { r = `No se pudo: ${m}`; }, resultado: () => r };
}

// Anillo 0 (entidad) y anillo 1 (caso de uso). Nada de formato ni de base adentro.
class ReglaRota extends Error {}
function nuevoDespacho({ id, destino, kg, centavos }) {
  if (!(kg > 0 && kg <= 1000)) throw new ReglaRota('el peso va de 0 a 1000 kg');
  return { id, destino, kg, centavos };
}
const crearCaso = ({ guardar, cotizar }) => async ({ destino, kg }, salida) => {
  try {
    const d = nuevoDespacho({ id: 'd1', destino, kg, centavos: await cotizar(kg) });
    await guardar(d);
    salida.exito({ id: d.id, destino: d.destino, kg: d.kg, centavos: d.centavos });  // datos simples hacia afuera
  } catch (e) {
    if (e instanceof ReglaRota) return salida.rechazo(e.message);
    throw e;
  }
};

// Anillo 2: tres presentadores que cumplen el mismo puerto de salida.
const comoJson = () => { let r; return { exito: (d) => (r = JSON.stringify(d)), rechazo: (m) => (r = JSON.stringify({ error: m })), ver: () => r }; };
const comoTexto = () => { let r; return { exito: (d) => (r = `${d.id}: ${d.kg} kg a ${d.destino}`), rechazo: (m) => (r = 'No se pudo: ' + m), ver: () => r }; };
const comoCsv = () => { let r; return { exito: (d) => (r = [d.id, d.destino, d.kg].join(';')), rechazo: (m) => (r = 'ERROR;' + m), ver: () => r }; };

const caso = crearCaso({ guardar: async () => {}, cotizar: async (kg) => 150000 + kg * 12000 });
for (const [nombre, mk] of [['json', comoJson], ['texto', comoTexto], ['csv', comoCsv]]) {
  for (const kg of [2, 5000]) {
    const s = mk(); await caso({ destino: '1000', kg }, s);
    console.log(nombre.padEnd(5), String(kg).padStart(4), '->', s.ver());
  }
}
